# ============================================================#  IMPLANTAR-FOTOS-WIKIDATA.ps1 - fallback de fotos oficiais via Wikidata#  Idempotente. Payload JS 100% ASCII. Validacao antes do commit.# ============================================================[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new()$repo='C:\Users\euler\votabrasil'[Environment]::CurrentDirectory=$repoSet-Location $repofunction Say($m){ Write-Host $m }if(-not (Test-Path (Join-Path $repo 'app\index.html'))){ Say 'ERRO: repo nao achado'; pause; exit 1 }# [0] runner dentro do repo (futuros 2 cliques vivem em scripts\)$sd=Join-Path $repo 'scripts'New-Item -ItemType Directory -Force -Path $sd | Out-Nullif($PSCommandPath){ Copy-Item $PSCommandPath (Join-Path $sd 'IMPLANTAR-FOTOS-WIKIDATA.ps1') -Force }$bat="@echo off`r`npowershell -NoProfile -ExecutionPolicy Bypass -File `"%~dp0IMPLANTAR-FOTOS-WIKIDATA.ps1`"`r`npause"[IO.File]::WriteAllText((Join-Path $sd 'RODAR-FOTOS.bat'),$bat,(New-Object System.Text.UTF8Encoding $false))Say '[0] runner instalado em scripts\RODAR-FOTOS.bat'# [1] modulo JS (ASCII-only; a prova viva roda no browser do usuario)$js=@'(function(){if(window.__vbwd)return;window.__vbwd=1;var CACHE='vb_wd_fotos',TTL=7*24*3600*1000,MAX=30;function load(){try{return JSON.parse(localStorage.getItem(CACHE)||'{}')}catch(e){return{}}}function save(c){try{localStorage.setItem(CACHE,JSON.stringify(c))}catch(e){}}function cUrl(f){return 'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(f)+'?width=240';}function api(u){return fetch(u).then(function(r){return r.json();});}function search(n){return api('https://www.wikidata.org/w/api.php?action=wbsearchentities&format=json&type=item&limit=3&language=pt&uselang=pt&origin=*&search='+encodeURIComponent(n));}function entity(id){return api('https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&props=claims&origin=*&ids='+id);}function photo(j,id){ var e=j.entities&&j.entities[id];if(!e||!e.claims)return null; var p31=(e.claims.P31||[]).some(function(c){var q=c.mainsnak&&c.mainsnak.datavalue&&c.mainsnak.datavalue.value;return q&&q.id==='Q5';}); if(!p31)return null; var c18=(e.claims.P18||[])[0];if(!c18)return null; var v=c18.mainsnak&&c18.mainsnak.datavalue&&c18.mainsnak.datavalue.value;return v||null;}function alvo(){ return [].slice.call(document.querySelectorAll('img')).filter(function(im){  var s=im.getAttribute('src')||'';return s.indexOf('ui-avatars.com')>-1; });}function nome(im){ var a=(im.getAttribute('alt')||'').trim();if(a)return a; var p=im.parentElement;for(var k=0;k<4&&p;k++){var t=p.querySelector('b,strong,h3,h4');if(t&&t.textContent.trim())return t.textContent.trim();p=p.parentElement;} return '';}var cache=load(),applied=0,warned=0;function run(){ var ims=alvo().slice(0,MAX);if(!ims.length)return; ims.forEach(function(im,i){  var nm=nome(im);if(!nm)return;  var key=nm.toLowerCase();  var hit=cache[key];  if(hit&&Date.now()-hit.t<TTL){if(hit.u){im.src=hit.u;applied++;}return;}  setTimeout(function(){   search(nm).then(function(j){    var s=(j.search||[]).slice(0,2);if(!s.length){cache[key]={t:Date.now(),u:null};save(cache);return;}    return entity(s[0].id).then(function(j2){     var f=photo(j2,s[0].id);     if(!f&&s[1]){return entity(s[1].id).then(function(j3){var f3=photo(j3,s[1].id);return finish(key,im,f3);});}     return finish(key,im,f);    });   }).catch(function(e){if(!warned){warned=1;console.warn('[wikidata] API indisponivel, mantendo avatares:',e&&e.message);}});  },i*350); }); setTimeout(function(){if(applied){console.log('[wikidata] fotos oficiais aplicadas: '+applied);applied=0;}},ims.length*350+1500);}function finish(key,im,f){ cache[key]={t:Date.now(),u:f?cUrl(f):null};save(cache); if(f){var old=im.getAttribute('src');im.setAttribute('data-fb',old||'');im.src=cUrl(f);applied++;  im.onerror=function(){im.onerror=null;if(old)im.src=old;cache[key]={t:Date.now(),u:null};save(cache);};}}var n=0,tm=setInterval(function(){run();if(++n>60)clearInterval(tm);},2500);window.addEventListener('load',function(){setTimeout(run,1200);});})();'@$jsPath=Join-Path $repo 'app\wikidata-fotos.js'[IO.File]::WriteAllText($jsPath,$js,(New-Object System.Text.UTF8Encoding $false))Say '[1] app\wikidata-fotos.js gravado'# [2] tag no app/index.html (idempotente)$ix=Join-Path $repo 'app\index.html'$c=[IO.File]::ReadAllText($ix)if(-not $c.Contains('wikidata-fotos.js')){  $tag="<script defer src=`"wikidata-fotos.js`"></script>"  $b=$c.LastIndexOf('</body>')  if($b -lt 0){ Say 'ERRO: sem </body> no app/index.html'; pause; exit 1 }  $c=$c.Substring(0,$b)+$tag+[char]10+$c.Substring($b)  [IO.File]::WriteAllText($ix,$c,(New-Object System.Text.UTF8Encoding $false))  Say '[2] tag defer injetada no app/index.html'} else { Say '[2] tag ja presente (idempotente)' }# [3] validacao ANTES do commit$ok = ([IO.File]::ReadAllText($jsPath)).Contains('wbsearchentities') -and ([IO.File]::ReadAllText($jsPath)).Contains('Q5') -and ([IO.File]::ReadAllText($ix)).Contains('wikidata-fotos.js')if(-not $ok){ Say 'VALIDACAO-FALHOU - nada commitado'; pause; exit 1 }# [4] commit + pushgit add -A$st=git status --porcelainif($st){ git commit -m "feat(fotos): fallback oficial via Wikidata (P18+P31:Q5, cache 7d, reversao segura)"; git push origin main; Say '[4] commit+push OK' }else { Say '[4] nada a commitar' }Say ''Say '=============== COMO VER FUNCIONANDO ==============='Say 'Abra xbrancox.github.io/votabrasil/app/ em aba nova (Ctrl+Shift+R).'Say 'Cards que hoje mostram avatar de iniciais (senadores, presidente, nao-incumbentes)'Say 'passarao a exibir foto real do Wikidata em ate ~10s (cadencia anti-rate-limit).'Say 'Console (F12) mostrara: [wikidata] fotos oficiais aplicadas: N'Say 'Se a API cair, o console avisa 1x e os avatares permanecem (degradacao graciosa).'Say ''Say '=========== PENDENCIAS (decisoes suas) ============='Say 'DOMINIO+EMAIL: registrar (sugestao votabrasil.app); trocar e-mails SO apos MX/SPF/DKIM + 3 caixas testadas.'Say 'FUNDO por candidato: gatilho = baixar zip prestacao TSE pelo Chrome (WAF 403 para robos).'Say 'Fotos Senado via API propria: extinta (404); Wikidata agora cobre esse buraco.'pause